import sys

from data_service.agent.sql_guard import SQL_GENERATION_RULES, guard_sql_query
from repro_config import load as load_repro_config

# Marshaled `_generation_prompt` still asks for "natural Persian". Rewrite at
# call time so Spider/BIRD generation stays English without patching bytecode.
_MARSHALED_GENERATION_PROMPT = globals().get("_generation_prompt")


def _english_generation_prompt(*args, **kwargs):
    if not callable(_MARSHALED_GENERATION_PROMPT):
        raise RuntimeError("marshaled _generation_prompt is unavailable")
    text = str(_MARSHALED_GENERATION_PROMPT(*args, **kwargs) or "")
    text = text.replace("question must be natural Persian.", "question must be natural English.")
    text = text.replace("natural Persian.", "natural English.")
    text = text.replace("natural Persian", "natural English")
    if SQL_GENERATION_RULES not in text:
        marker = "Return ONLY JSON with keys question and sql."
        if marker in text:
            text = text.replace(marker, marker + "\n" + SQL_GENERATION_RULES, 1)
        else:
            text = SQL_GENERATION_RULES + "\n" + text
    return text


if callable(_MARSHALED_GENERATION_PROMPT):
    _generation_prompt = _english_generation_prompt

_MARSHALED_GUARD_CANDIDATE = globals().get("guard_candidate_sql")


def _research_guard_candidate_sql(
    sql,
    *,
    dialect="mysql",
    limit=0,
    allowed_tables=None,
):
    """Bypass the marshaled product default of LIMIT 100."""
    try:
        cap = int(limit)
    except (TypeError, ValueError):
        cap = 0
    if cap == 100:
        cap = 0
    return guard_sql_query(
        sql,
        dialect=dialect,
        limit=cap,
        allowed_tables=allowed_tables,
        sqlite_mode=str(dialect).lower() in {"sqlite", "sqlite3"},
        question="",
    )


if callable(_MARSHALED_GUARD_CANDIDATE):
    guard_candidate_sql = _research_guard_candidate_sql

if callable(globals().get("quote_mysql_schema_idents")):
    quote_mysql_schema_idents.__doc__ = (
        "Backtick non-ASCII or spaced identifiers the LLM left unquoted."
    )

_REPRO = load_repro_config()
_KEYWORD_SCORES = tuple(
    (str(name), float(score))
    for name, score in _REPRO["icrl"]["keyword_scores"].items()
)


def _floats_in(code) -> list[float]:
    found: list[float] = []
    for const in code.co_consts:
        if isinstance(const, float):
            found.append(const)
        elif hasattr(const, "co_consts"):
            found.extend(_floats_in(const))
    return found


_baked = [value for value in _floats_in(generate_pair.__code__) if value not in (0.0, 1.0)]
_declared = float(_REPRO["temperature"]["icrl"])
if _baked and abs(_baked[0] - _declared) > 1e-9:
    raise SystemExit(
        "ICRL generate_pair temperature "
        f"{_baked[0]} does not match configs/repro.yaml temperature.icrl {_declared}"
    )

complexity_reward.__doc__ = """
Lexical complexity reward for one candidate SQL string.

reward(sql) = sum of keyword weights for non-overlapping matches.
Pad the SQL with a leading and trailing space, uppercase it, and scan
``icrl.keyword_scores`` from configs/repro.yaml, longest phrase first.
A match counts only when both neighbors are not alphanumeric (or the match
touches the pad) and the character span was not already claimed by a longer
phrase. Each accepted match adds its weight once.

Weights: INNER/LEFT/RIGHT JOIN, GROUP BY, HAVING, CASE, AVG, SUM, COUNT, MIN,
MAX = 3; ORDER BY, JOIN, WHERE, DISTINCT, BETWEEN, LIKE, WHEN, THEN, ELSE, ON,
IN = 2; FROM, SELECT, LIMIT, AND, OR, NOT, END, ASC, DESC = 1.

Split: none. The reward is not execution accuracy and is not computed on
Spider train or Spider dev. ``generate_pair`` calls the router at
temperature.icrl and keeps a refinement only when this reward rises and the
candidate still executes on the source database. Easy-band pairs are not
refined. Pool insert and delete happen in
``bootstrap_fewshots_for_source``, not here.
""".strip()


def warn_if_reward_on_dev() -> None:
    """Print a loud warning when the reward is declared on the dev split."""
    split = str(_REPRO["icrl"]["reward_split"]).strip().lower()
    consts = " ".join(
        str(const)
        for const in complexity_reward.__code__.co_consts
        if isinstance(const, str)
    ).lower()
    if split == "dev" or "spider_dev" in consts or "dev.json" in consts:
        print(
            "\n"
            "!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!\n"
            "WARNING: ICRL reward is computed on the Spider DEV split.\n"
            "!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!\n",
            file=sys.stderr,
        )


warn_if_reward_on_dev()
